import {$,esc,load,save,notify} from '../../project-kit.js';
const KEY='dock-time-zones-v1',local=Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC';
const formatterCache=new Map();
function formatters(zone){let value=formatterCache.get(zone);if(!value){value={clock:new Intl.DateTimeFormat(undefined,{timeZone:zone,hour:'numeric',minute:'2-digit'}),day:new Intl.DateTimeFormat(undefined,{timeZone:zone,weekday:'short',month:'short',day:'numeric',year:'numeric'}),offset:new Intl.DateTimeFormat('en',{timeZone:zone,timeZoneName:'longOffset'}),hour:new Intl.DateTimeFormat('en-GB',{timeZone:zone,hour:'numeric',hourCycle:'h23'})};formatterCache.set(zone,value)}return value}
function valid(zone){try{formatters(zone).clock.format();return typeof zone==='string'&&zone.length<=100}catch{return false}}
function canonical(zone){return formatters(zone).clock.resolvedOptions().timeZone}
let zones=load(KEY,[local,'Europe/London','Asia/Tokyo']);zones=Array.isArray(zones)?[...new Set(zones.filter(valid).map(canonical))].slice(0,12):[local];if(!zones.length)zones=[local];let instant=null;
$('#local-zone').textContent='Your device’s time zone: '+local;
const supported=Intl.supportedValuesOf?.('timeZone')||['UTC',local,'America/Denver','America/New_York','Europe/London','Asia/Tokyo','Australia/Sydney'];$('#zone-options').innerHTML=supported.map(z=>`<option value="${esc(z)}"></option>`).join('');
function details(zone,date){const f=formatters(zone),clock=f.clock.format(date),day=f.day.format(date),offset=f.offset.formatToParts(date).find(p=>p.type==='timeZoneName')?.value||'',hour=Number(f.hour.format(date));return{clock,day,offset,period:hour>=9&&hour<18?'Daytime':hour>=18&&hour<22?'Evening':'Early / late'}}
function render(){const now=instant||new Date();$('#mode').textContent=instant?'Meeting preview · '+now.toLocaleString()+' in your device’s time zone.':'Live · updates every second using your device clock.';$('#zones').innerHTML=zones.map(z=>{const d=details(z,now);return`<article class="zone-card" data-zone="${esc(z)}"><div class="zone-city"><strong>${esc(z.split('/').at(-1).replace(/_/g,' '))}${z===canonical(local)?' · you':''}</strong><span class="zone-label">${esc(z)} · ${esc(d.offset)}</span><br><span class="zone-period">${d.period}</span></div><div class="zone-clock-wrap"><div class="zone-clock">${esc(d.clock)}</div><div class="zone-day">${esc(d.day)}</div></div><button class="zone-remove" data-remove="${esc(z)}" aria-label="Remove ${esc(z)}" ${zones.length===1?'disabled':''}>×</button></article>`}).join('');document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const previous=zones;zones=zones.filter(z=>z!==b.dataset.remove);if(!save(KEY,zones)){zones=previous;render();return}render()})}
function add(zone){if(!valid(zone))return notify('Choose a valid IANA time zone, such as America/Denver.');zone=canonical(zone);if(zones.includes(zone))return notify('That time zone is already shown.');if(zones.length>=12)return notify('Keep up to 12 time zones. Remove one first.');zones.push(zone);if(!save(KEY,zones)){zones.pop();return}$('#new-zone').value='';render()}
$('#add').onsubmit=e=>{e.preventDefault();add($('#new-zone').value.trim())};document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>add(b.dataset.preset));$('#meeting').onchange=()=>{const input=$('#meeting').value;if(!input){instant=null;render();return}const date=new Date(input);if(!Number.isFinite(date.getTime()))return notify('Choose a valid date and time.');const normalized=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}T${String(date.getHours()).padStart(2,'0')}:${String(date.getMinutes()).padStart(2,'0')}`;if(normalized!==input.slice(0,16)){instant=null;$('#meeting').value='';render();return notify('That local time does not exist during the daylight-saving change. Choose another time.')}instant=date;render()};$('#live').onclick=()=>{instant=null;$('#meeting').value='';render()};$('#copy').onclick=async()=>{const date=instant||new Date(),text=(instant?'Meeting times':'Current times')+'\n'+zones.map(z=>{const d=details(z,date);return`${z}: ${d.clock}, ${d.day} (${d.offset})`}).join('\n');try{await navigator.clipboard.writeText(text);notify('Times copied.')}catch{notify('Clipboard unavailable. Select the times on screen to copy them.')}};function tick(){if(instant||document.visibilityState!=='visible')return;const now=new Date();for(const card of document.querySelectorAll('[data-zone]')){const z=card.dataset.zone,d=details(z,now);card.querySelector('.zone-clock').textContent=d.clock;card.querySelector('.zone-day').textContent=d.day;card.querySelector('.zone-period').textContent=d.period;card.querySelector('.zone-label').textContent=z+' · '+d.offset}}setInterval(tick,1000);render();
